void main() {
  IntegrationTestWidgetsFlutterBinding.ensureInitialized();
  testWidgets('native element scroll geometry matches Chromium oracle', (
    tester,
  ) async {
    final gateway = Gateway();
    final theme = await PircTheme.load();
    final server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
    final origin = 'http://127.0.0.1:${server.port}';
    final token = 'pirc_dev_${List.filled(43, 'A').join()}';
    var page = '';
    final receipts = <String>[];
    final failures = <String>[];
    final accepted = <Map<String, dynamic>>[];
    final listener = server.listen((request) async {
      try {
        await request.drain<void>();
        if (request.headers.value('authorization') != 'Bearer $token') {
          failures.add('Missing synthetic bearer');
        }
        receipts.add(request.uri.path);
        if (request.uri.path == '/api/sessions') {
          request.response.headers.contentType = ContentType.json;
          request.response.write('{"sessions":[]}');
        } else if (request.uri.path == '/page') {
          request.response.headers.contentType = ContentType(
            'text',
            'html',
            charset: 'utf-8',
          );
          request.response.write(page);
        } else {
          failures.add('Unexpected path ${request.uri}');
          request.response.statusCode = 404;
        }
        await request.response.close();
      } catch (error) {
        failures.add('$error');
      }
    });

    try {
      await gateway.call('pair', {
        'link': Uri(
          scheme: 'pirc',
          host: 'pair',
          queryParameters: {'url': origin, 'token': token},
        ).toString(),
      });
      tester.view.devicePixelRatio = 1;

      for (final item in oracle) {
        final width = (item['viewportWidth'] as num).toDouble();
        final height = (item['viewportHeight'] as num).toDouble();
        final brightness = item['theme'] == 'dark'
            ? Brightness.dark
            : Brightness.light;
        final targets = (item['targets'] as List).cast<String>();
        final actions = item['actions'] as List;
        tester.view.physicalSize = Size(width, height);
        page = (item['authoredHTML'] as String).replaceFirst(
          '</body>',
          '${_controls(targets, actions)}</body>',
        );

        final windows = NativeDocumentWindows(gateway);
        final window = windows.target('', null, sourceUrl: '$origin/page');
        NativeFetchedDocument? document;
        try {
          expect(
            await window.load(
              NativeHtmlFormRequest(
                url: '$origin/page',
                method: 'GET',
                target: '',
              ),
              baseUrl: origin,
            ),
            NativeDocumentLoadResult.committed,
          );
          windows.select(window);
          document = window.currentDocument!;
          await tester.pumpWidget(
            MaterialApp(
              theme: theme.build(brightness),
              home: Scaffold(
                body: NativeDocumentScope(
                  documentUrl: '$origin/page',
                  windows: windows,
                  window: window,
                  child: NativeFetchedDocumentView(
                    document: document,
                    gateway: gateway,
                    onLink: (_) {},
                    onSubmit: (_) {},
                  ),
                ),
              ),
            ),
          );
          await tester.pumpAndSettle();

          final scripts = document.scripts!;
          await _waitForDOMContentLoaded(tester, document);
          final parsed = html.parse(scripts.content!.text);
          expect(parsed.getElementById('apply-next-scroll'), isNotNull);
          expect(parsed.getElementById('read-scroll-state'), isNotNull);

          // Initial geometry is read only after DCL and native layout complete.
          var observed = await _tapReadAndWait(tester, document, 0);
          final browserStages =
              (item['expected'] as Map<String, dynamic>)['stages'] as List;
          _expectStage(
            observed,
            browserStages.first as Map<String, dynamic>,
            targets,
            '${item['name']} initial ${width.toInt()} ${item['theme']}',
            0,
          );
          _expectStage(
            Map<String, dynamic>.from(observed['dclInitial'] as Map),
            browserStages.first as Map<String, dynamic>,
            targets,
            '${item['name']} DOMContentLoaded ${width.toInt()} ${item['theme']}',
            0,
          );

          for (var index = 0; index < actions.length; index++) {
            final label = (actions[index] as Map<String, dynamic>)['label'];
            await _tapApplyAndPump(tester, document);
            // Scroll actions are applied by the native viewport host after the
            // script turn; finish its frames before asking the page to read.
            await tester.pump();
            await tester.pump();
            observed = await _tapReadAndWait(tester, document, index + 1);
            _expectStage(
              observed,
              browserStages[index + 1] as Map<String, dynamic>,
              targets,
              '${item['name']} $label ${width.toInt()} ${item['theme']}',
              index + 1,
            );
          }

          expect(
            tester.takeException(),
            isNull,
            reason: item['name'] as String,
          );
          accepted.add({
            'case': item['name'],
            'viewportWidth': width,
            'theme': item['theme'],
            'stages': browserStages.length,
            'status': 'matches-tested-browser-geometry-and-scroll-events',
          });
        } finally {
          await tester.pumpWidget(const SizedBox());
          windows.dispose();
          if (document?.scripts case final scripts?) await scripts.closed;
        }
      }

      expect(failures, isEmpty);
      expect(receipts, isNotEmpty);
      debugPrintSynchronously(
        'PIRC_ELEMENT_SCROLL_ACCEPTANCE ${jsonEncode({'browserVersion': '153.0.8010.12', 'cases': accepted, 'httpReceipts': receipts, 'failures': failures})}',
      );
    } finally {
      tester.view.reset();
      await listener.cancel();
      await server.close(force: true);
    }
  });
}

String _controls(List<String> targets, List actions) =>
    '''
<button id="apply-next-scroll" type="button">Apply next scroll</button>
<button id="read-scroll-state" type="button">Read scroll state</button>
<div id="scroll-stage-label" style="position:fixed;left:0;top:0;z-index:2147483647;background:white;color:black;white-space:nowrap"></div>
<pre id="scroll-json-probe" style="position:fixed;left:0;top:0;width:0;height:0;overflow:hidden"></pre>
<script>
window.__scrollTargetIds=${jsonEncode(targets)};
window.__scrollActions=${jsonEncode(actions)};
window.__nextScrollAction=0;
window.__scrollEvents=[];
window.__readScrollStage=function(){
  var boxes={};
  window.__scrollTargetIds.forEach(function(id){
    var e=document.getElementById(id),r=e.getBoundingClientRect();
    boxes[id]={rect:r.toJSON(),clientRects:Array.from(e.getClientRects()).map(function(x){return x.toJSON()}),
      clientWidth:e.clientWidth,clientHeight:e.clientHeight,clientLeft:e.clientLeft,clientTop:e.clientTop,
      offsetWidth:e.offsetWidth,offsetHeight:e.offsetHeight,scrollWidth:e.scrollWidth,scrollHeight:e.scrollHeight,
      scrollLeft:e.scrollLeft,scrollTop:e.scrollTop};
  });
  return {targets:boxes,scrollX:window.scrollX,scrollY:window.scrollY,scrollEvents:window.__scrollEvents.slice()};
};
window.__scrollTargetIds.forEach(function(id){
  var e=document.getElementById(id);
  e.addEventListener('scroll',function(){window.__scrollEvents.push({target:id,scrollLeft:e.scrollLeft,scrollTop:e.scrollTop})});
});
window.__applyScrollAction=function(){
  var action=window.__scrollActions[window.__nextScrollAction];
  if(!action)return;
  function target(id){var e=document.getElementById(id);if(!e)throw new Error('Missing target '+id);return e;}
  function applyOne(id,op,left,top){var e=target(id);if(op==='set'){e.scrollLeft=left;e.scrollTop=top;}else if(op==='scrollTo'){e.scrollTo(left,top);}else if(op==='scrollBy'){e.scrollBy(left,top);}else throw new Error('Bad scroll op '+op);}
  if(action.op==='setBoth')action.ids.forEach(function(id){applyOne(id,'set',0,action.top)});
  else if(action.op==='setSequence')action.sequence.forEach(function(v){applyOne(v.id,'set',v.left==null?0:v.left,v.top==null?0:v.top)});
  else applyOne(action.id,action.op==='set'?'set':action.op,action.left==null?0:action.left,action.top==null?0:action.top);
  window.__nextScrollAction++;
};
document.getElementById('apply-next-scroll').addEventListener('click',window.__applyScrollAction);
document.getElementById('read-scroll-state').addEventListener('click',function(){
  var output=window.__readScrollStage();
  output.stage=window.__nextScrollAction;
  output.dclInitial=window.__dclInitial;
  document.getElementById('scroll-json-probe').textContent=JSON.stringify(output);
  document.getElementById('scroll-stage-label').textContent='scroll stage '+output.stage;
});
document.addEventListener('DOMContentLoaded',function(){window.__dclInitial=window.__readScrollStage();window.__dclInitial.stage=0;document.getElementById('scroll-stage-label').textContent='DOMContentLoaded';});
</script>
''';

Future<void> _waitForDOMContentLoaded(
  WidgetTester tester,
  NativeFetchedDocument document,
) async {
  for (var turn = 0; turn < 120; turn++) {
    await tester.pump(const Duration(milliseconds: 25));
    final scripts = document.scripts;
    if (scripts == null || !scripts.ready) continue;
    final label = html
        .parse(scripts.content?.text ?? '')
        .getElementById('scroll-stage-label')
        ?.text;
    if (label == 'DOMContentLoaded') return;
  }
  fail('DOMContentLoaded and native script readiness did not arrive in time.');
}

Finder _button(String label) => find.byWidgetPredicate(
  (widget) => widget is NativeHtmlButtonWidget && widget.button.label == label,
);

Future<void> _tapApplyAndPump(
  WidgetTester tester,
  NativeFetchedDocument document,
) async {
  await tester.ensureVisible(_button('Apply next scroll'));
  await tester.tap(_button('Apply next scroll'));
  for (var turn = 0; turn < 8; turn++) {
    await tester.pump(const Duration(milliseconds: 25));
  }
  expect(
    document.scripts?.ready,
    isTrue,
    reason: 'Native script runtime stays ready after an actual UI tap.',
  );
}

Future<Map<String, dynamic>> _tapReadAndWait(
  WidgetTester tester,
  NativeFetchedDocument document,
  int expectedStage,
) async {
  await tester.ensureVisible(_button('Read scroll state'));
  await tester.tap(_button('Read scroll state'));
  for (var turn = 0; turn < 120; turn++) {
    await tester.pump(const Duration(milliseconds: 25));
    final scripts = document.scripts;
    if (scripts == null || !scripts.ready) continue;
    final page = html.parse(scripts.content?.text ?? '');
    final probe = page.getElementById('scroll-json-probe')?.text;
    if (probe == null || !probe.startsWith('{')) continue;
    final result = Map<String, dynamic>.from(jsonDecode(probe) as Map);
    final stageLabel = page.getElementById('scroll-stage-label')?.text;
    if (result['stage'] == expectedStage &&
        stageLabel == 'scroll stage $expectedStage') {
      return result;
    }
  }
  fail('Read scroll state did not publish stage $expectedStage in time.');
}

void _expectStage(
  Map<String, dynamic> observed,
  Map<String, dynamic> browserStage,
  List<String> targetIds,
  String label,
  int expectedStageIndex,
) {
  final actualTargets = Map<String, dynamic>.from(observed['targets'] as Map);
  final expectedTargets = Map<String, dynamic>.from(
    browserStage['targets'] as Map,
  );
  expect(
    actualTargets.keys.toSet(),
    targetIds.toSet(),
    reason: '$label targets',
  );
  expect(
    observed['scrollX'],
    browserStage['scrollX'],
    reason: '$label scrollX',
  );
  expect(
    observed['scrollY'],
    browserStage['scrollY'],
    reason: '$label scrollY',
  );

  for (final id in targetIds) {
    final actual = Map<String, dynamic>.from(actualTargets[id] as Map);
    final expected = Map<String, dynamic>.from(expectedTargets[id] as Map);
    final actualRect = Map<String, dynamic>.from(actual['rect'] as Map);
    final expectedRect = Map<String, dynamic>.from(expected['rect'] as Map);
    for (final key in ['x', 'y', 'width', 'height']) {
      expect(
        (actualRect[key] as num).toDouble(),
        closeTo((expectedRect[key] as num).toDouble(), .3),
        reason: '$label #$id BCR.$key',
      );
    }
    for (final key in [
      'offsetWidth',
      'offsetHeight',
      'clientWidth',
      'clientHeight',
      'clientLeft',
      'clientTop',
      'scrollWidth',
      'scrollHeight',
    ]) {
      expect(actual[key], expected[key], reason: '$label #$id $key');
    }
    for (final key in ['scrollLeft', 'scrollTop']) {
      expect(
        (actual[key] as num).toDouble(),
        closeTo((expected[key] as num).toDouble(), .3),
        reason: '$label #$id $key',
      );
    }
    final actualRects = actual['clientRects'] as List;
    final expectedRects = expected['clientRects'] as List;
    expect(
      actualRects,
      hasLength(expectedRects.length),
      reason: '$label #$id clientRects',
    );
    for (var index = 0; index < expectedRects.length; index++) {
      final actualClientRect = Map<String, dynamic>.from(
        actualRects[index] as Map,
      );
      final expectedClientRect = Map<String, dynamic>.from(
        expectedRects[index] as Map,
      );
      for (final key in ['x', 'y', 'width', 'height']) {
        expect(
          (actualClientRect[key] as num).toDouble(),
          closeTo((expectedClientRect[key] as num).toDouble(), .3),
          reason: '$label #$id clientRects[$index].$key',
        );
      }
    }
  }

  final actualEvents = (observed['scrollEvents'] as List)
      .map((event) => Map<String, dynamic>.from(event as Map))
      .toList();
  final expectedEvents = (browserStage['scrollEvents'] as List)
      .map((event) => Map<String, dynamic>.from(event as Map))
      .toList();
  expect(
    actualEvents,
    hasLength(expectedEvents.length),
    reason: '$label scroll event count',
  );
  for (var index = 0; index < expectedEvents.length; index++) {
    expect(
      actualEvents[index]['target'],
      expectedEvents[index]['target'],
      reason: '$label event[$index] target',
    );
    for (final key in ['scrollLeft', 'scrollTop']) {
      expect(
        (actualEvents[index][key] as num).toDouble(),
        closeTo((expectedEvents[index][key] as num).toDouble(), .3),
        reason: '$label event[$index] $key',
      );
    }
  }
  expect(observed['stage'], expectedStageIndex, reason: '$label stage index');
}
